// burns-by-burner.mjs — Census (B): burns decomposed by burner, parameterized by token.
// Provenance: MONARK, branch lot/census-next-piece; generated by worker model claude-opus-4-8[1m]
// (effort max), 2026-09-18, under docs/PLAN-census-next-piece.md (B-H1..B-H4) — MEASURE ONLY, no
// calibration, no committed fixture, no public text. Reviewed adversarially by the orchestrator (R-21).
//
// REUSE (per mission): the RPC/window layer of scripts/usde-full-pull.mjs (endpoint pool + per-endpoint
// cooldown, recursive split-on-result-limit getLogs, sumBurnsMints `top byFrom`, C1 identity, v_t) and
// apps/sentinel/src/windows.ts (daysUTC, firstBlockAtOrAfter — imported UNCHANGED). QUORUM added from
// apps/sentinel/src/rpc.ts (providerOf): every window aggregate (burns/mints/byFrom AND totalSupply) is
// recomputed on TWO DISTINCT PROVIDERS; bytes must match or the window is flagged `disagree` (via a status
// string here, never dropped silently). Fewer than two providers answering -> `no_quorum` (the single value
// is kept and flagged). Read-only public RPC, NO KEY, no other outbound action.
//
// MEASURED 2026-09-18 (probe, this branch): the usde-full-pull pool is NOT reusable as-is — publicnode
// 403s, llamarpc DNS-fails, ankr needs a key, drpc/blastapi 400 on eth_getLogs. Only two DISTINCT
// providers serve archive eth_getLogs without a key: mevblocker.io and tenderly.co (two tenderly aliases
// = one provider). Both returned byte-identical archive results on 3 cross-checks, which rehabilitates
// mevblocker (the FDUSD scouting had flagged it "suspect"). Archive eth_call (totalSupply) is served by
// more providers (drpc, blastapi, pokt in addition), so supply quorum is broader.
//
// USAGE: node scripts/census/burns-by-burner.mjs <fdusd|susde|gho|usdtb> [--budget N] [--maxday YYYY-MM-DD]
//   Resumable: appends per-window records to docs/census-2026-09-18/data/B-<token>-windows.jsonl and
//   skips days already present. Stops cleanly when the call budget is hit (mission cap: 6000 TOTAL).

import { readFileSync, existsSync, appendFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { daysUTC, firstBlockAtOrAfter } from '../../apps/sentinel/src/windows.ts';
import { providerOf } from '../../apps/sentinel/src/rpc.ts';

// ------------------------------------------------------------------ keccak256 (validated at startup)
const RC = [0x0000000000000001n,0x0000000000008082n,0x800000000000808an,0x8000000080008000n,0x000000000000808bn,0x0000000080000001n,0x8000000080008081n,0x8000000000008009n,0x000000000000008an,0x0000000000000088n,0x0000000080008009n,0x000000008000000an,0x000000008000808bn,0x800000000000008bn,0x8000000000008089n,0x8000000000008003n,0x8000000000008002n,0x8000000000000080n,0x000000000000800an,0x800000008000000an,0x8000000080008081n,0x8000000000008080n,0x0000000080000001n,0x8000000080008008n];
const RHO = [0,1,62,28,27,36,44,6,55,20,3,10,43,25,39,41,45,15,21,8,18,2,61,56,14];
const M64 = (1n << 64n) - 1n;
const rotl = (x, n) => ((x << BigInt(n)) | (x >> BigInt(64 - n))) & M64;
function keccakF(s) { for (let r = 0; r < 24; r++) { const C = new Array(5); for (let x = 0; x < 5; x++) C[x] = s[x] ^ s[x+5] ^ s[x+10] ^ s[x+15] ^ s[x+20]; const D = new Array(5); for (let x = 0; x < 5; x++) D[x] = C[(x+4)%5] ^ rotl(C[(x+1)%5], 1); for (let x = 0; x < 5; x++) for (let y = 0; y < 5; y++) s[x+5*y] ^= D[x]; const B = new Array(25).fill(0n); for (let x = 0; x < 5; x++) for (let y = 0; y < 5; y++) B[y+5*((2*x+3*y)%5)] = rotl(s[x+5*y], RHO[x+5*y]); for (let x = 0; x < 5; x++) for (let y = 0; y < 5; y++) s[x+5*y] = B[x+5*y] ^ ((~B[(x+1)%5+5*y] & M64) & B[(x+2)%5+5*y]); s[0] ^= RC[r]; } }
function keccak256(bytes) { const rate = 136; const s = new Array(25).fill(0n); const p = [...bytes]; p.push(0x01); while (p.length % rate !== 0) p.push(0); p[p.length-1] ^= 0x80; for (let off = 0; off < p.length; off += rate) { for (let i = 0; i < rate/8; i++) { let lane = 0n; for (let j = 7; j >= 0; j--) lane = (lane << 8n) | BigInt(p[off+i*8+j]); s[i] ^= lane; } keccakF(s); } let out = ''; for (let i = 0; i < 4; i++) { let lane = s[i]; for (let j = 0; j < 8; j++) { out += (lane & 0xffn).toString(16).padStart(2, '0'); lane >>= 8n; } } return out; }
const sel = (sig) => '0x' + keccak256([...Buffer.from(sig, 'utf8')]).slice(0, 8);
const topicOf = (sig) => '0x' + keccak256([...Buffer.from(sig, 'utf8')]);
function assertKeccak() {
  const cases = [
    [keccak256([]), 'c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470'],
    [keccak256([...Buffer.from('Transfer(address,address,uint256)','utf8')]), 'ddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef'],
    [sel('totalSupply()'), '0x18160ddd'], [sel('balanceOf(address)'), '0x70a08231'], [sel('transfer(address,uint256)'), '0xa9059cbb'],
  ];
  for (const [got, exp] of cases) { if (got.toLowerCase() !== exp.toLowerCase()) throw new Error(`keccak self-check FAILED: ${got} != ${exp}`); }
}

// selectors / topics (all [lu]: derived by validated keccak)
const TRANSFER_TOPIC = topicOf('Transfer(address,address,uint256)');
const SEL = { totalSupply: sel('totalSupply()'), symbol: sel('symbol()'), decimals: sel('decimals()'), name: sel('name()'),
  cooldownShares: sel('cooldownShares(uint256)'), cooldownAssets: sel('cooldownAssets(uint256)'),
  getFacilitatorsList: sel('getFacilitatorsList()'), getFacilitator: sel('getFacilitator(address)'), silo: sel('silo()') };
const ZERO40 = '0'.repeat(40);
const ZERO32 = '0x' + '0'.repeat(64);
const USDE_TOKEN = '0x4c9EDD5852cd905f086C759E8383e09bff1E68B3'; // Ethena USDe (for sUSDe unstake check)

// ------------------------------------------------------------------ token config
const TODAY_EXCL = '2026-09-18'; // last COMPLETE UTC day = 2026-09-17 (today in progress); overridable via --maxday
const daysAgo = (n) => { const d = new Date(TODAY_EXCL + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() - n); return d.toISOString().slice(0, 10); };
function buildRanges(spec, maxExcl) {
  const out = [];
  for (const r of spec) {
    if (r === 'RECENT90') out.push([daysAgo(90), maxExcl]);
    else if (r === 'RECENT30') out.push([daysAgo(30), maxExcl]);
    else out.push(r);
  }
  return out;
}
const TOKENS = {
  fdusd: { symbol: 'FDUSD', address: '0xc5f0f7b66764F6ec8C8Dff7BA683102295E16409', decimals: 18,
    rangeSpec: [['2025-01-01', '2025-07-01'], 'RECENT90'], holdout: ['2025-04-03'],
    knownBurner: '0xfa771871d3d5c85e156d3d379e2ff7699c4d6a66' /* Safe, per SCOUTING-F-fdusd.md */ },
  susde: { symbol: 'sUSDe', address: '0x9d39a5de30e57443bff2a8307a4256c8797a3497', decimals: 18, rangeSpec: ['RECENT30'], holdout: [] },
  gho:   { symbol: 'GHO', address: '0x40D16FC0246aD3160Ccc09B8D0D3A2cD28aE6C2f', decimals: 18, rangeSpec: ['RECENT90'], holdout: [] },
  usdtb: { symbol: 'USDtb', address: '0xC139190F447e929f090Edeb554D95AbB8b18aC1C', decimals: 18, rangeSpec: ['RECENT90'], holdout: [] }, // address: investor 2026-09-18 (Ethena docs / @ethena launch tweet / Etherscan tag), orchestrator-verified eth_call (symbol USDtb, decimals 18, totalSupply ~483M)
};

// ------------------------------------------------------------------ RPC pool (usde-full-pull pattern + roles)
// Load-spread (measured 2026-09-18): only mevblocker.io + tenderly.co serve archive eth_getLogs, so they
// are RESERVED for the logs quorum (one hit each per window). Supply/block reads are offloaded to
// drpc/blastapi/pokt (which serve archive eth_call + headers but reject getLogs) so mevblocker/tenderly
// never rate-limit under load. Quorum still needs TWO DISTINCT providers on each aggregate.
const EP = {
  logs:   ['https://rpc.mevblocker.io', 'https://gateway.tenderly.co/public/mainnet', 'https://mainnet.gateway.tenderly.co'],
  supply: ['https://eth.drpc.org', 'https://eth-mainnet.public.blastapi.io', 'https://eth-pokt.nodies.app', 'https://gateway.tenderly.co/public/mainnet', 'https://rpc.mevblocker.io'],
  block:  ['https://eth.drpc.org', 'https://eth-mainnet.public.blastapi.io', 'https://gateway.tenderly.co/public/mainnet', 'https://eth-pokt.nodies.app', 'https://rpc.mevblocker.io'],
};
let callCount = 0, BUDGET = 6000;
const cooldownUntil = new Map();
const now = () => Date.now();
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const toHexBlock = (n) => '0x' + BigInt(n).toString(16);
const isResultLimit = (m) => /more than|result|range is too|10000|query returned|limit exceeded|block range|too large|response size/i.test(m);
const isRateLimit = (m) => /usage limit|rate.?limit|-32001|\b429\b|too many|plan|quota|capacity|exceeded the/i.test(m);

// ONE round-trip to a NAMED endpoint. Every POST counts (incl. retries). Throws tagged on error.
async function rpcOnce(url, method, params, timeoutMs = 25000) {
  if (callCount >= BUDGET) throw new Error(`BUDGET_EXCEEDED at ${callCount}`);
  callCount++;
  const ctl = new AbortController();
  const to = setTimeout(() => ctl.abort(), timeoutMs);
  try {
    const res = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ jsonrpc: '2.0', id: callCount, method, params }), signal: ctl.signal });
    if (!res.ok) { const e = new Error(`HTTP ${res.status} ${url}`); e.rate = res.status === 429 || res.status === 503; throw e; }
    const json = await res.json();
    if (json.error) { const m = JSON.stringify(json.error); const e = new Error(`${m} @${url}`); e.rate = isRateLimit(m); e.resultLimit = isResultLimit(m); throw e; }
    if (json.result === undefined) throw new Error(`no result @${url}`);
    return json.result;
  } finally { clearTimeout(to); }
}
// retry ONE endpoint a few times (benching on rate-limit); throw on persistent failure or result-limit (caller splits).
async function callEndpoint(url, method, params, tries = 3) {
  let lastErr;
  for (let t = 0; t < tries; t++) {
    if ((cooldownUntil.get(url) || 0) > now()) { lastErr = new Error(`benched ${url}`); await sleep(150); continue; }
    try { return await rpcOnce(url, method, params); }
    catch (e) { lastErr = e; if (String(e.message).includes('BUDGET_EXCEEDED')) throw e; if (e.resultLimit) throw e; cooldownUntil.set(url, now() + (e.rate ? 20000 : 6000)); await sleep(150 * (t + 1)); }
  }
  throw lastErr;
}

// Quorum read: get one success from each of TWO DISTINCT providers (provider = providerOf, so tenderly
// aliases count once), each provider retried with backoff to ride out transient rate-limits BEFORE
// declaring no_quorum (advisor: retry per provider before giving up). Compare with eq() -> ok|disagree.
async function quorumRead(role, fetchOne, eq, describe) {
  const provToUrls = new Map();
  for (const u of EP[role]) { const p = providerOf(u); if (!provToUrls.has(p)) provToUrls.set(p, []); provToUrls.get(p).push(u); }
  const results = []; let lastErr;
  for (const [prov, urls] of provToUrls) {
    if (results.length >= 2) break;
    let val, okp = false;
    for (let attempt = 0; attempt < 4 && !okp; attempt++) {
      for (const url of urls) { try { val = await fetchOne(url); okp = true; break; } catch (e) { if (String(e.message).includes('BUDGET_EXCEEDED')) throw e; lastErr = e; } }
      if (!okp) await sleep(700 * (attempt + 1));
    }
    if (okp) results.push({ prov, val });
  }
  if (results.length >= 2) {
    const agree = eq(results[0].val, results[1].val);
    return { status: agree ? 'ok' : 'disagree', value: results[0].val, valueB: agree ? undefined : results[1].val, providers: [results[0].prov, results[1].prov] };
  }
  if (results.length === 1) return { status: 'no_quorum', value: results[0].val, providers: [results[0].prov], note: `only ${results[0].prov}${lastErr ? '; last ' + String(lastErr.message).slice(0, 50) : ''}` };
  throw new Error(`${role} ${describe || ''}: no provider answered${lastErr ? ' — ' + String(lastErr.message).slice(0, 80) : ''}`);
}

// eth_getLogs on ONE endpoint, splitting the range recursively on a result-limit. Single attempt
// (quorumRead owns retries); the split keeps each sub-query under provider result caps. `topics`
// defaults to the full Transfer set (window pull sums burns+mints from it); the sUSDe/silo probes
// pass a narrower topic filter so they return few logs.
async function getLogsVia(url, address, from, to, topics = [TRANSFER_TOPIC], depth = 0) {
  try {
    return await rpcOnce(url, 'eth_getLogs', [{ address, fromBlock: toHexBlock(from), toBlock: toHexBlock(to), topics }]);
  } catch (e) {
    if ((e.resultLimit || isResultLimit(String(e.message))) && to > from && depth < 18) {
      const mid = from + Math.floor((to - from) / 2);
      const [a, b] = await Promise.all([getLogsVia(url, address, from, mid, topics, depth + 1), getLogsVia(url, address, mid + 1, to, topics, depth + 1)]);
      return [...a, ...b];
    }
    throw e;
  }
}

// ------------------------------------------------------------------ flow aggregation (usde-full-pull sumBurnsMints + full byFrom + tx sets)
function computeFlow(logs) {
  let burns = 0n, mints = 0n, burnEvents = 0, mintEvents = 0;
  const byFrom = {}; const burnTx = new Map(); const mintTx = new Set();
  for (const l of logs) {
    const from = l.topics[1].slice(-40), to = l.topics[2].slice(-40), v = BigInt(l.data);
    if (to === ZERO40) { burns += v; burnEvents++; byFrom[from] = (byFrom[from] || 0n) + v; burnTx.set(l.transactionHash, (burnTx.get(l.transactionHash) || 0n) + v); }
    if (from === ZERO40) { mints += v; mintEvents++; mintTx.add(l.transactionHash); }
  }
  // mint+burn in the SAME tx: burn amount whose tx also carried a mint
  let mbCount = 0, mbAmount = 0n;
  for (const [tx, amt] of burnTx) if (mintTx.has(tx)) { mbCount++; mbAmount += amt; }
  return { burns, mints, burnEvents, mintEvents, byFrom, mbCount, mbAmount, logCount: logs.length };
}
const flowDigest = (f) => createHash('sha256').update(`${f.burns}|${f.mints}|${f.burnEvents}|${f.mintEvents}|${Object.entries(f.byFrom).sort().map(([a, v]) => a + ':' + v.toString()).join(',')}`).digest('hex');
function topBurners(byFrom, n = 3) { return Object.entries(byFrom).sort((a, b) => (b[1] > a[1] ? 1 : -1)).slice(0, n).map(([a, r]) => ({ addr: '0x' + a, raw: r.toString() })); }

// ------------------------------------------------------------------ block boundary (interpolation-seeded, exact via windows.ts)
const blockTsMemo = new Map();
async function getBlockTs(block) {
  if (blockTsMemo.has(block)) return blockTsMemo.get(block);
  const r = await singleBlockRead('eth_getBlockByNumber', [toHexBlock(block), false]);
  const ts = parseInt(r.timestamp, 16); blockTsMemo.set(block, ts); return ts;
}
async function singleBlockRead(method, params) {
  // block header is objective; use the block pool round-robin with fallback (no quorum needed — timestamps are consensus).
  let lastErr;
  for (const url of EP.block) { try { const r = await callEndpoint(url, method, params); if (r) return r; } catch (e) { lastErr = e; if (String(e.message).includes('BUDGET_EXCEEDED')) throw e; } }
  throw lastErr || new Error(`${method}: no block endpoint answered`);
}
async function finalizedBlock() {
  const r = await singleBlockRead('eth_getBlockByNumber', ['finalized', false]);
  return { block: parseInt(r.number, 16), ts: parseInt(r.timestamp, 16) };
}
// Resolve firstBlockAtOrAfter(targetTs) cheaply: interpolate from a seed {block,ts} to within a few
// blocks (~12.06 s/slot post-merge), narrow-bracket, then call windows.ts firstBlockAtOrAfter UNCHANGED
// over the tiny bracket. getBlockTs is memoized so the bracket-check and the search share reads.
async function resolveBoundary(targetTs, seed, latest) {
  const SLOT = 12.06;
  let guess = Math.max(1, Math.min(latest, seed.block + Math.round((targetTs - seed.ts) / SLOT)));
  let guessTs = await getBlockTs(guess);
  for (let k = 0; k < 3; k++) { const delta = Math.round((targetTs - guessTs) / SLOT); if (Math.abs(delta) <= 2) break; guess = Math.max(1, Math.min(latest, guess + delta)); guessTs = await getBlockTs(guess); }
  let lo = guess, hi = guess;
  if (guessTs < targetTs) { let step = 4; hi = Math.min(latest, guess + step); while (await getBlockTs(hi) < targetTs) { lo = hi; step *= 2; hi = Math.min(latest, hi + step); if (hi >= latest) { hi = latest; break; } } }
  else { let step = 4; lo = Math.max(1, guess - step); while (await getBlockTs(lo) >= targetTs) { hi = lo; step *= 2; lo = Math.max(1, lo - step); if (lo <= 1) { lo = 1; break; } } }
  const b = await firstBlockAtOrAfter(targetTs, lo, hi, getBlockTs);
  return { block: b, ts: await getBlockTs(b) };
}

// ------------------------------------------------------------------ supply (quorum, cached, chained)
const supplyCache = new Map(); // block -> record
async function supplyAt(tokenAddr, block) {
  if (supplyCache.has(block)) return supplyCache.get(block);
  const rec = await quorumRead('supply', (url) => rpcOnce(url, 'eth_call', [{ to: tokenAddr, data: SEL.totalSupply }, toHexBlock(block)]).then((h) => BigInt(h)), (a, b) => a === b, `supply@${block}`);
  supplyCache.set(block, rec);
  return rec;
}

// ------------------------------------------------------------------ per-window pull
const U = (raw, dec) => Number(raw / (10n ** BigInt(dec) / 1000000n)) / 1000000;
async function pullWindow(cfg, day, regime, fromBlock, toBlock) {
  // flow (quorum on burns/mints/byFrom digest)
  let flowRec;
  try {
    flowRec = await quorumRead('logs', (url) => getLogsVia(url, cfg.address, fromBlock, toBlock), (a, b) => flowDigest(computeFlow(a)) === flowDigest(computeFlow(b)), `flow ${day}`);
  } catch (e) { if (String(e.message).includes('BUDGET_EXCEEDED')) throw e; return { day, regime, fromBlock, toBlock, status: 'error', error: String(e.message).slice(0, 160) }; }
  const flow = computeFlow(flowRec.value);
  const flowStatus = flowRec.status; // ok | disagree | no_quorum
  // supply (chained: S_open(D) block == S_close(D-1) block via cache)
  const openBlk = fromBlock - 1, closeBlk = toBlock;
  let sOpen, sClose;
  try { sOpen = await supplyAt(cfg.address, openBlk); sClose = await supplyAt(cfg.address, closeBlk); }
  catch (e) { if (String(e.message).includes('BUDGET_EXCEEDED')) throw e; return { day, regime, fromBlock, toBlock, status: 'error', error: 'supply ' + String(e.message).slice(0, 140) }; }
  const supplyStatus = (sOpen.status === 'ok' && sClose.status === 'ok') ? 'ok' : (sOpen.status === 'disagree' || sClose.status === 'disagree') ? 'disagree' : 'no_quorum';
  // C1: S_close + burns - mints == S_open
  const c1_ok = sClose.value + flow.burns - flow.mints === sOpen.value;
  const c1_diff = (sOpen.value - (sClose.value + flow.burns - flow.mints)).toString();
  const v_t_per_hr = sOpen.value > 0n ? Number((flow.burns * 1000000n) / sOpen.value) / 1000000 / 24 : null;
  const burns_frac_sopen = sOpen.value > 0n ? Number((flow.burns * 1000000000n) / sOpen.value) / 1000000000 : null;
  const overall = ['error', 'disagree', 'no_quorum', 'ok'].find((s) => flowStatus === s || supplyStatus === s) || 'ok';
  return {
    day, regime, fromBlock, toBlock, status: overall, flowStatus, supplyStatus,
    flowProviders: flowRec.providers, supplyProviders: [sOpen.providers, sClose.providers],
    burns: flow.burns.toString(), mints: flow.mints.toString(), burnEvents: flow.burnEvents, mintEvents: flow.mintEvents, logCount: flow.logCount,
    byFrom: Object.fromEntries(Object.entries(flow.byFrom).map(([a, v]) => ['0x' + a, v.toString()])),
    topBurners: topBurners(flow.byFrom), mintBurnSameTx: { count: flow.mbCount, amount: flow.mbAmount.toString() },
    supplyOpen: sOpen.value.toString(), supplyClose: sClose.value.toString(),
    burnsUnits: U(flow.burns, cfg.decimals), mintsUnits: U(flow.mints, cfg.decimals), supplyOpenUnits: U(sOpen.value, cfg.decimals), supplyCloseUnits: U(sClose.value, cfg.decimals),
    c1_ok, c1_diff, v_t_per_hr, burns_frac_sopen,
    ...(flowStatus === 'disagree' ? { flowDisagreeB: (() => { const g = computeFlow(flowRec.valueB); return { burns: g.burns.toString(), mints: g.mints.toString() }; })() } : {}),
  };
}

// ------------------------------------------------------------------ token metadata (eth_call, [lu])
function decString(hex) { const h = hex.startsWith('0x') ? hex.slice(2) : hex; const off = Number(BigInt('0x' + h.slice(0, 64))) * 2; const len = Number(BigInt('0x' + h.slice(off, off + 64))); return Buffer.from(h.slice(off + 64, off + 64 + len * 2), 'hex').toString('utf8'); }
async function verifyMetadata(cfg) {
  const symRaw = await callEndpoint(EP.supply[1], 'eth_call', [{ to: cfg.address, data: SEL.symbol }, 'latest']);
  const decRaw = await callEndpoint(EP.supply[1], 'eth_call', [{ to: cfg.address, data: SEL.decimals }, 'latest']);
  let sym; try { sym = decString(symRaw); } catch { sym = symRaw; }
  const dec = Number(BigInt(decRaw));
  console.log(`METADATA ${cfg.symbol} ${cfg.address}: symbol="${sym}" decimals=${dec} (expected symbol ${cfg.symbol}, decimals ${cfg.decimals}) via ${providerOf(EP.supply[1])}`);
  if (dec !== cfg.decimals) throw new Error(`decimals mismatch: on-chain ${dec} != config ${cfg.decimals}`);
  return { sym, dec };
}

// ------------------------------------------------------------------ token extras
function decodeFacilitator(hex) { const h = hex.slice(2); const t = Number(BigInt('0x' + h.slice(0, 64))) * 2; const so = Number(BigInt('0x' + h.slice(t + 128, t + 192))) * 2; const p = t + so; const len = Number(BigInt('0x' + h.slice(p, p + 64))); return { cap: BigInt('0x' + h.slice(t, t + 64)), lvl: BigInt('0x' + h.slice(t + 64, t + 128)), label: Buffer.from(h.slice(p + 64, p + 64 + len * 2), 'hex').toString('utf8').trim() }; }
async function ghoFacilitators() {
  const url = EP.logs[1];
  const listHex = await callEndpoint(url, 'eth_call', [{ to: TOKENS.gho.address, data: SEL.getFacilitatorsList }, 'latest']);
  const h = listHex.slice(2); const n = Number(BigInt('0x' + h.slice(64, 128))); const addrs = [];
  for (let i = 0; i < n; i++) addrs.push('0x' + h.slice(128 + i * 64 + 24, 128 + (i + 1) * 64));
  const map = {};
  for (const a of addrs) { const f = await callEndpoint(url, 'eth_call', [{ to: TOKENS.gho.address, data: SEL.getFacilitator + a.slice(2).padStart(64, '0') }, 'latest']); const d = decodeFacilitator(f); map[a.toLowerCase()] = { label: d.label, capacity: d.cap.toString(), level: d.lvl.toString() }; }
  return map;
}
async function susdeCooldownProbe(outPath) {
  const url = EP.logs[1]; const T = TOKENS.susde.address;
  // find recent sUSDe burns
  const latest = (await finalizedBlock()).block;
  const from = latest - 14 * 7200;
  const burns = await getLogsVia(url, T, from, latest, [TRANSFER_TOPIC, null, ZERO32]); // sUSDe Transfer->0x0 only
  const byTx = new Map();
  for (const l of burns) byTx.set(l.transactionHash, { block: parseInt(l.blockNumber, 16), owner: '0x' + l.topics[1].slice(-40), shares: (byTx.get(l.transactionHash)?.shares || 0n) + BigInt(l.data) });
  const picks = [...byTx.entries()].slice(0, 3);
  const results = [];
  for (const [tx, info] of picks) {
    const txObj = await callEndpoint(url, 'eth_getTransactionByHash', [tx]);
    const rc = await callEndpoint(url, 'eth_getTransactionReceipt', [tx]);
    const input = txObj.input; const selector = input.slice(0, 10);
    const arg = input.length >= 74 ? BigInt('0x' + input.slice(10, 74)) : null;
    const isCooldownShares = selector.toLowerCase() === SEL.cooldownShares.toLowerCase();
    const isCooldownAssets = selector.toLowerCase() === SEL.cooldownAssets.toLowerCase();
    const argEqShares = arg !== null && arg === info.shares;
    const susdeBurnLogs = rc.logs.filter((l) => l.address.toLowerCase() === T.toLowerCase() && l.topics[0].toLowerCase() === TRANSFER_TOPIC.toLowerCase() && l.topics[2].slice(-40) === ZERO40);
    const sBefore = await supplyAt(T, info.block - 1); const sAfter = await supplyAt(T, info.block);
    results.push({ tx, block: info.block, owner: info.owner, selector, calledContract: txObj.to,
      matches: isCooldownShares ? 'cooldownShares' : isCooldownAssets ? 'cooldownAssets' : 'other', arg: arg?.toString(), sharesBurned: info.shares.toString(), argEqualsShares: argEqShares,
      receiptHasSusdeBurnToZero: susdeBurnLogs.length > 0, susdeBurnCountInTx: susdeBurnLogs.length,
      totalSupplyBefore: sBefore.value.toString(), totalSupplyAfter: sAfter.value.toString(), supplyDelta: (sBefore.value - sAfter.value).toString(), supplyDeltaEqShares: (sBefore.value - sAfter.value) === info.shares });
  }
  // unstake emits nothing on sUSDe: a USDe Transfer FROM the silo should carry NO sUSDe log
  const silo = '0x' + (await callEndpoint(url, 'eth_call', [{ to: T, data: SEL.silo }, 'latest'])).slice(-40);
  const usdeFromSilo = await getLogsVia(url, USDE_TOKEN, latest - 14 * 7200, latest, [TRANSFER_TOPIC, '0x' + silo.slice(2).padStart(64, '0')]);
  let unstakeCheck = { found: usdeFromSilo.length, siloVerified: silo, sample: null };
  if (usdeFromSilo.length) { const s = usdeFromSilo[usdeFromSilo.length - 1]; const rc = await callEndpoint(url, 'eth_getTransactionReceipt', [s.transactionHash]); const hasSusde = rc.logs.some((l) => l.address.toLowerCase() === T.toLowerCase()); unstakeCheck.sample = { tx: s.transactionHash, usdeOut: BigInt(s.data).toString(), receiptTouchesSusde: hasSusde }; }
  const out = { note: 'sUSDe cooldownShares(uint256) -> Transfer(owner->0x0) on sUSDe token (burn at file ENTRY); unstake moves USDe out of silo, no sUSDe event', selector_cooldownShares: SEL.cooldownShares, selector_cooldownAssets: SEL.cooldownAssets, silo, cooldownTxs: results, unstakeCheck };
  appendFileSync(outPath, JSON.stringify(out) + '\n');
  return out;
}

// ------------------------------------------------------------------ main
async function main() {
  assertKeccak();
  const token = (process.argv[2] || '').toLowerCase();
  const cfg = TOKENS[token];
  if (!cfg) { console.error('usage: burns-by-burner.mjs <fdusd|susde|gho|usdtb> [--budget N] [--maxday YYYY-MM-DD]'); process.exit(2); }
  for (let i = 3; i < process.argv.length; i++) { if (process.argv[i] === '--budget') BUDGET = parseInt(process.argv[++i]); if (process.argv[i] === '--maxday') global.__maxday = process.argv[++i]; }
  const maxExcl = global.__maxday || TODAY_EXCL;
  console.log(`=== Census B :: ${cfg.symbol} :: budget ${BUDGET} calls :: maxExcl ${maxExcl} ===`);

  if (!cfg.address) { // USDtb NOT FOUND path
    console.log('USDtb: address NOT FOUND. RPC-only mission (no web); repo holds no USDtb address; symbol()=="USDtb" would prove self-declaration not canonicity (bare [2nd] = defect per doc 03). B-H3 => NOT FOUND. Formed procurement request emitted in the report. No windows pulled.');
    return;
  }

  mkdirSync(new URL('../../docs/census-2026-09-18/data/', import.meta.url), { recursive: true });
  const outPath = new URL(`../../docs/census-2026-09-18/data/B-${token}-windows.jsonl`, import.meta.url);
  await verifyMetadata(cfg);

  // GHO facilitator labels first (classification key) — non-fatal (window pull must survive a probe hiccup)
  if (token === 'gho') { try { const fac = await ghoFacilitators(); appendFileSync(new URL('../../docs/census-2026-09-18/data/B-gho-facilitators.jsonl', import.meta.url), JSON.stringify({ asOf: 'latest', facilitators: fac }) + '\n'); console.log('GHO facilitators:', Object.entries(fac).map(([a, f]) => `${a}=${f.label}`).join(' | ')); } catch (e) { console.log('WARN gho facilitators failed (non-fatal):', String(e.message).slice(0, 120)); } }
  // sUSDe cooldown/unstake analysis — non-fatal
  if (token === 'susde') { try { const c = await susdeCooldownProbe(new URL('../../docs/census-2026-09-18/data/B-susde-cooldown.jsonl', import.meta.url)); console.log('sUSDe cooldown probe:', c.cooldownTxs.length, 'txs;', JSON.stringify(c.cooldownTxs.map((t) => ({ m: t.matches, argEqShares: t.argEqualsShares, burnToZero: t.receiptHasSusdeBurnToZero, supplyDeltaEqShares: t.supplyDeltaEqShares })))); console.log('  unstake check:', JSON.stringify(c.unstakeCheck)); } catch (e) { console.log('WARN susde cooldown probe failed (non-fatal):', String(e.message).slice(0, 120)); } }

  // build windows
  const ranges = buildRanges(cfg.rangeSpec, maxExcl);
  const holdout = new Set(cfg.holdout);
  const allDays = [];
  for (const [s, e] of ranges) for (const [fromTs, toTs, day] of daysUTC(s, e)) allDays.push({ day, fromTs, toTs, regime: holdout.has(day) ? 'holdout' : 'calm' });
  // dedup days (recent ranges may overlap none here, but be safe) preserving order
  const seenDay = new Set(); const days = allDays.filter((d) => (seenDay.has(d.day) ? false : seenDay.add(d.day)));
  console.log(`windows: ${days.length} UTC days across ${ranges.length} range(s): ${ranges.map((r) => r.join('..')).join(' , ')}`);

  // resume
  const done = new Set();
  if (existsSync(outPath)) for (const line of readFileSync(outPath, 'utf8').split('\n')) { if (line.trim()) try { done.add(JSON.parse(line).day); } catch {} }
  console.log(`resume: ${done.size} days already present`);

  const fin = await finalizedBlock();
  // boundary cache day-> {fromBlock,fromTs}; resolve sequentially, seed marching (bootstrap from finalized)
  let seed = fin;
  const boundary = new Map(); // dayStartTs -> {block, ts}
  async function boundaryAt(ts) { if (boundary.has(ts)) return boundary.get(ts); const b = await resolveBoundary(ts, seed, fin.block); boundary.set(ts, b); seed = b; return b; }

  let pulled = 0, stopped = false;
  for (const d of days) {
    if (done.has(d.day)) continue;
    if (callCount >= BUDGET - 20) { stopped = true; break; }
    try {
      const start = await boundaryAt(d.fromTs);
      const nextStart = await boundaryAt(d.toTs);
      const fromBlock = start.block, toBlock = nextStart.block - 1;
      if (toBlock > fin.block) { console.log(`${d.day}: beyond finalized (${toBlock} > ${fin.block}) — skipped (not yet final)`); continue; }
      const rec = await pullWindow(cfg, d.day, d.regime, fromBlock, toBlock);
      appendFileSync(outPath, JSON.stringify(rec) + '\n');
      pulled++;
      if (rec.status !== 'ok' || !rec.c1_ok || rec.burnEvents > 0) console.log(`${d.day} [${d.regime}] ${rec.status} c1=${rec.c1_ok} burns=${rec.burnsUnits?.toFixed(2)} bev=${rec.burnEvents} mev=${rec.mintEvents} v=${rec.v_t_per_hr?.toExponential?.(2)} | calls=${callCount}`);
    } catch (e) {
      if (String(e.message).includes('BUDGET_EXCEEDED')) { stopped = true; break; }
      appendFileSync(outPath, JSON.stringify({ day: d.day, regime: d.regime, status: 'error', error: String(e.message).slice(0, 180) }) + '\n');
      console.log(`${d.day} ERROR ${String(e.message).slice(0, 120)} | calls=${callCount}`);
    }
  }

  // summary + sha256
  const rows = existsSync(outPath) ? readFileSync(outPath, 'utf8').split('\n').filter((l) => l.trim()).map((l) => JSON.parse(l)) : [];
  const sha = createHash('sha256').update(readFileSync(outPath, 'utf8').replace(/\r\n/g, '\n'), 'utf8').digest('hex');
  const byStatus = {}; for (const r of rows) byStatus[r.status] = (byStatus[r.status] || 0) + 1;
  const c1fail = rows.filter((r) => r.status !== 'error' && r.c1_ok === false).length;
  console.log(`\nSUMMARY ${cfg.symbol}: ${rows.length} windows, status=${JSON.stringify(byStatus)}, c1_fail=${c1fail}, budget used=${callCount}/${BUDGET}${stopped ? ' [STOPPED — resume to continue]' : ''}`);
  console.log(`JSONL sha256=${sha}  ${outPath.pathname}`);
}
main().catch((e) => { console.error('FATAL', e); process.exit(1); });
